class Renderer {
public:
  Renderer() : current_(&buffers_[0]), next_(&buffers_[1]) {}

  void renderFrame(const World& world) {
    next_->clear();
    world.drawInto(*next_);
    // Ghost trail: blend with the LAST frame, which lives in current_,
    // not with whatever is left over in next_ (that is two frames old).
    next_->blendFrom(*current_, 0.3f);
    waitForVBlank();
    swap();
  }

  const Framebuffer& getBuffer() const { return *current_; } // video driver

private:
  void swap() { std::swap(current_, next_); }

  Framebuffer buffers_[2];
  Framebuffer* current_;
  Framebuffer* next_;
};

class NavGridManager {
public:
  NavGridManager() : current_(&grids_[0]), next_(&grids_[1]) {}

  // Called every frame; does a slice of the rebuild work.
  void tickRebuild() {
    if (!rebuilding_) return;
    next_->rebuildChunk(chunk_++);
    if (chunk_ == NavGrid::NUM_CHUNKS) {
      std::swap(current_, next_);  // publish atomically
      rebuilding_ = false;
    }
  }

  Path findPath(Vec2 from, Vec2 to) const {
    return current_->findPath(from, to);  // never sees half-built data
  }

private:
  NavGrid grids_[2];
  NavGrid* current_;
  NavGrid* next_;
  int chunk_ = 0;
  bool rebuilding_ = false;
};

struct InfluenceLayer {
  InfluenceMap maps[2];
  int current = 0;

  const InfluenceMap& read() const { return maps[current]; }
  InfluenceMap& write() { return maps[1 - current]; }
  void swap() { current = 1 - current; }   // O(1), no memcpy
};

