void FireSystem::tick() {
  for (int y = 0; y < H; y++) {
    for (int x = 0; x < W; x++) {
      Tile t = current_->at(x, y);          // read old state only
      if (t.flammable && !t.burning &&
          current_->anyNeighborBurning(x, y)) {
        t.burning = true;
      }
      next_->at(x, y) = t;                  // write every cell of next
    }
  }
  std::swap(current_, next_);               // all tiles change at once
}

class CrowdNpc {
public:
  static void swapAll() { current_ = next(); }   // once per frame

  void setAlert(float a) { alert_[next()] = a; } // fully rewritten each frame
  float alert() const { return alert_[current_]; }

private:
  static int current_;
  static int next() { return 1 - current_; }
  float alert_[2];
};

// Event flags: monolithic, cleared in one pass.
struct HitBuffer {
  std::bitset<MAX_NPCS> bits[2];
  int cur = 0;
  void hit(int npc) { bits[1 - cur].set(npc); }
  bool wasHit(int npc) const { return bits[cur].test(npc); }
  void swap() { cur = 1 - cur; bits[1 - cur].reset(); }
};
